455	      {
456	        ...opts,
457	        headers
458	      },
459	      new CacheRevalidationHandler(
460	        (success, context, statusCode, headers) => {
461	          if (success) {
462	            if (statusCode === 304) {
463	              if (revalidationResponseDisallowsCachedReuse(globalOpts.type, headers)) {
464	                if (util.isStream(result.body)) {
465	                  result.body.on('error', nop).destroy()
466	                }
467	
468	                deleteCachedValue(globalOpts.store, cacheKey)
469	                return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
470	              }
471	
472	              if (revalidationResponseUpdatesCacheControl(headers)) {
473	                deleteCachedValue(globalOpts.store, cacheKey)
474	              }
475	            }
476	
477	            // TODO: successful revalidation should be considered fresh (not give stale warning).
478	            sendCachedValue(handler, opts, result, age, context, stale)
