let dispatcherOriginCounter = 0

/**
 * Mints the placeholder origin used for requests that reach an interceptor
 * without one. It is stable for every request made through the same composed
 * dispatcher — a Client or Pool only ever talks to a single origin — and unique
 * across dispatchers, so two of them sharing a cache store can never read each
 * other's entries.
 *
 * @returns {string}
 */
function makeDispatcherOrigin () {
  return `http://dispatcher-${++dispatcherOriginCounter}.undici.invalid`
}

/**
 * Interceptors only see `opts.origin` when they sit on an Agent; a Client or
 * Pool applies its own origin after the interceptor chain has already run.
 * Without an origin every request would collapse onto the same key, so recover
 * it from an absolute-form path when there is one and use the dispatcher's
 * placeholder origin otherwise.
 *
 * @param {import('../../types/dispatcher.d.ts').default.DispatchOptions} opts
 * @param {string} [fallbackOrigin] origin to use when `opts` carries none
 * @returns {string | undefined}
 */
function getEffectiveOrigin (opts, fallbackOrigin) {
  if (opts.origin) {
    return opts.origin.toString()
  }

  const path = opts.path
  if (typeof path === 'string' && (path.startsWith('http://') || path.startsWith('https://'))) {
    try {
      return new URL(path).origin
    } catch {
      // Not a usable absolute-form path, fall back below.
    }
  }

  return fallbackOrigin
