'use strict'

const { createServer } = require('node:http')
const { describe, test, after } = require('node:test')
const { once } = require('node:events')
const { equal, strictEqual } = require('node:assert')
const { setTimeout: sleep } = require('node:timers/promises')
const { Client, Pool, interceptors, cacheStores: { MemoryCacheStore } } = require('../../index')

// A Client or Pool applies its own origin after the interceptor chain has run,
// so `opts.origin` is undefined by the time cache() and deduplicate() build
// their keys. These tests pin down that both still work without one.
describe('Interceptors composed on a Client or Pool', () => {
  test('cache() caches requests dispatched by a Client', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, (_, res) => {
      requestsToOrigin++
      res.setHeader('cache-control', 's-maxage=10')
      res.end('asd')
    }).listen(0)

    const client = new Client(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(async () => {
      server.close()
      await client.close()
    })

    await once(server, 'listening')

    const request = { method: 'GET', path: '/' }

    {
      const res = await client.request(request)
      equal(requestsToOrigin, 1)
      strictEqual(await res.body.text(), 'asd')
    }

    {
      const res = await client.request(request)
      equal(requestsToOrigin, 1)
      strictEqual(await res.body.text(), 'asd')
    }
  })

  test('cache() caches requests dispatched by a Pool', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, (_, res) => {
      requestsToOrigin++
      res.setHeader('cache-control', 's-maxage=10')
      res.end('asd')
    }).listen(0)

    const pool = new Pool(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(async () => {
      server.close()
      await pool.close()
    })

    await once(server, 'listening')

    const request = { method: 'GET', path: '/' }

    {
      const res = await pool.request(request)
      equal(requestsToOrigin, 1)
      strictEqual(await res.body.text(), 'asd')
    }

    {
      const res = await pool.request(request)
      equal(requestsToOrigin, 1)
      strictEqual(await res.body.text(), 'asd')
    }
  })

  test('cache() keeps two Clients sharing a store apart', async () => {
    let requestsToFirstOrigin = 0
    const firstServer = createServer({ joinDuplicateHeaders: true }, (_, res) => {
      requestsToFirstOrigin++
      res.setHeader('cache-control', 's-maxage=10')
      res.end('first')
    }).listen(0)

    let requestsToSecondOrigin = 0
    const secondServer = createServer({ joinDuplicateHeaders: true }, (_, res) => {
      requestsToSecondOrigin++
      res.setHeader('cache-control', 's-maxage=10')
      res.end('second')
    }).listen(0)

    const store = new MemoryCacheStore()

    const firstClient = new Client(`http://localhost:${firstServer.address().port}`)
      .compose(interceptors.cache({ store }))
    const secondClient = new Client(`http://localhost:${secondServer.address().port}`)
      .compose(interceptors.cache({ store }))

    after(async () => {
      firstServer.close()
      secondServer.close()
      await firstClient.close()
      await secondClient.close()
    })

    await Promise.all([once(firstServer, 'listening'), once(secondServer, 'listening')])

    const request = { method: 'GET', path: '/' }

    strictEqual(await (await firstClient.request(request)).body.text(), 'first')

    // Same path and method, different origin: must not be served from the
    // first client's cache entry.
    strictEqual(await (await secondClient.request(request)).body.text(), 'second')
    equal(requestsToFirstOrigin, 1)
    equal(requestsToSecondOrigin, 1)

    // Both are cached under their own key.
    strictEqual(await (await firstClient.request(request)).body.text(), 'first')
    strictEqual(await (await secondClient.request(request)).body.text(), 'second')
    equal(requestsToFirstOrigin, 1)
    equal(requestsToSecondOrigin, 1)
  })

  test('deduplicate() dedupes requests dispatched by a Client', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, async (_, res) => {
      requestsToOrigin++
      await sleep(100)
      res.end('response-body')
    }).listen(0)

    const client = new Client(`http://localhost:${server.address().port}`)
      .compose(interceptors.deduplicate())

    after(async () => {
      server.close()
      await client.close()
    })

    await once(server, 'listening')

    const request = { method: 'GET', path: '/' }

    const [res1, res2, res3] = await Promise.all([
      client.request(request),
      client.request(request),
      client.request(request)
    ])

    equal(requestsToOrigin, 1)

    const bodies = await Promise.all([res1.body.text(), res2.body.text(), res3.body.text()])
    for (const body of bodies) {
      strictEqual(body, 'response-body')
    }
  })

  test('deduplicate() dedupes requests dispatched by a Pool', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, async (_, res) => {
      requestsToOrigin++
      await sleep(100)
      res.end('response-body')
    }).listen(0)

    const pool = new Pool(`http://localhost:${server.address().port}`)
      .compose(interceptors.deduplicate())

    after(async () => {
      server.close()
      await pool.close()
    })

    await once(server, 'listening')

    const request = { method: 'GET', path: '/' }

    const [res1, res2, res3] = await Promise.all([
      pool.request(request),
      pool.request(request),
      pool.request(request)
    ])

    equal(requestsToOrigin, 1)

    const bodies = await Promise.all([res1.body.text(), res2.body.text(), res3.body.text()])
    for (const body of bodies) {
      strictEqual(body, 'response-body')
    }
  })

  test('deduplicate() keeps two Clients apart', async () => {
    let requestsToFirstOrigin = 0
    const firstServer = createServer({ joinDuplicateHeaders: true }, async (_, res) => {
      requestsToFirstOrigin++
      await sleep(100)
      res.end('first')
    }).listen(0)

    let requestsToSecondOrigin = 0
    const secondServer = createServer({ joinDuplicateHeaders: true }, async (_, res) => {
      requestsToSecondOrigin++
      await sleep(100)
      res.end('second')
    }).listen(0)

    const deduplicate = interceptors.deduplicate()

    const firstClient = new Client(`http://localhost:${firstServer.address().port}`)
      .compose(deduplicate)
    const secondClient = new Client(`http://localhost:${secondServer.address().port}`)
      .compose(deduplicate)

    after(async () => {
      firstServer.close()
      secondServer.close()
      await firstClient.close()
      await secondClient.close()
    })

    await Promise.all([once(firstServer, 'listening'), once(secondServer, 'listening')])

    const request = { method: 'GET', path: '/' }

    const [first, second] = await Promise.all([
      firstClient.request(request),
      secondClient.request(request)
    ])

    equal(requestsToFirstOrigin, 1)
    equal(requestsToSecondOrigin, 1)
    strictEqual(await first.body.text(), 'first')
    strictEqual(await second.body.text(), 'second')
  })
})

