    const [res1, res2, res3] = await Promise.all([
      pool.request(request),
      pool.request(request),
      pool.request(request)
    ])

    equal(requestsToOrigin, 1)

    const bodies = await Promise.all([res1.body.text(), res2.body.text(), res3.body.text()])
    for (const body of bodies) {
      strictEqual(body, 'response-body')
    }
  })

  test('deduplicate() keeps two Clients apart', async () => {
    let requestsToFirstOrigin = 0
    const firstServer = createServer({ joinDuplicateHeaders: true }, async (_, res) => {
      requestsToFirstOrigin++
      await sleep(100)
      res.end('first')
    }).listen(0)

    let requestsToSecondOrigin = 0
    const secondServer = createServer({ joinDuplicateHeaders: true }, async (_, res) => {
      requestsToSecondOrigin++
      await sleep(100)
      res.end('second')
    }).listen(0)

    const deduplicate = interceptors.deduplicate()

    const firstClient = new Client(`http://localhost:${firstServer.address().port}`)
      .compose(deduplicate)
    const secondClient = new Client(`http://localhost:${secondServer.address().port}`)
      .compose(deduplicate)

    after(async () => {
      firstServer.close()
      secondServer.close()
      await firstClient.close()
      await secondClient.close()
    })

    await Promise.all([once(firstServer, 'listening'), once(secondServer, 'listening')])

    const request = { method: 'GET', path: '/' }

    const [first, second] = await Promise.all([
      firstClient.request(request),
      secondClient.request(request)
    ])

    equal(requestsToFirstOrigin, 1)
    equal(requestsToSecondOrigin, 1)
    strictEqual(await first.body.text(), 'first')
    strictEqual(await second.body.text(), 'second')
  })
})

